BEGIN;
CREATE TABLE users(id uuid PRIMARY KEY, email text UNIQUE NOT NULL CHECK(email=lower(email)), password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('STUDENT','MENTOR','ADMIN')), membership_status text NOT NULL DEFAULT 'PENDING' CHECK(membership_status IN ('PENDING','APPROVED','REJECTED','SUSPENDED','INACTIVE')), register_number text UNIQUE NOT NULL, failed_attempts integer NOT NULL DEFAULT 0, locked_until timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions(token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE profiles(user_id uuid PRIMARY KEY REFERENCES users(id), display_name text NOT NULL, bio text NOT NULL DEFAULT '', department text NOT NULL DEFAULT '', academic_year integer CHECK(academic_year BETWEEN 1 AND 6), skills text[] NOT NULL DEFAULT '{}', interests text[] NOT NULL DEFAULT '{}', portfolio_url text, github_url text, photo_document_id uuid, public_visible boolean NOT NULL DEFAULT false, publication_approved boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE projects(id uuid PRIMARY KEY, title text NOT NULL, domain text NOT NULL, abstract text NOT NULL, problem_statement text NOT NULL, objectives text NOT NULL, expected_outcome text NOT NULL, lead_id uuid NOT NULL REFERENCES users(id), mentor_id uuid REFERENCES users(id), technology_stack text[] NOT NULL DEFAULT '{}', repository_url text, demo_url text, start_date date NOT NULL, target_date date NOT NULL CHECK(target_date>=start_date), status text NOT NULL DEFAULT 'PROPOSED' CHECK(status IN ('PROPOSED','APPROVED','ACTIVE','ON_HOLD','COMPLETED','ARCHIVED')), review_notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE project_members(project_id uuid REFERENCES projects(id), user_id uuid REFERENCES users(id), assigned_role text NOT NULL, PRIMARY KEY(project_id,user_id));
CREATE TABLE milestones(id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects(id), title text NOT NULL, due_date date NOT NULL, completed boolean NOT NULL DEFAULT false);
CREATE TABLE tasks(id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects(id), assignee_id uuid NOT NULL REFERENCES users(id), title text NOT NULL, status text NOT NULL DEFAULT 'NOT_STARTED' CHECK(status IN ('NOT_STARTED','IN_PROGRESS','BLOCKED','SUBMITTED','REVIEWED','COMPLETED')), due_date date NOT NULL, UNIQUE(id,project_id), FOREIGN KEY(project_id,assignee_id) REFERENCES project_members(project_id,user_id));
CREATE TABLE contributions(id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects(id), student_id uuid NOT NULL REFERENCES users(id), task_id uuid, contribution_date date NOT NULL, work_area text NOT NULL, description text NOT NULL, outcome text NOT NULL, evidence_url text, status text NOT NULL DEFAULT 'SUBMITTED' CHECK(status IN ('SUBMITTED','REVISION_REQUIRED','VERIFIED')), review_notes text, reviewer_id uuid REFERENCES users(id), reviewed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(task_id,project_id) REFERENCES tasks(id,project_id), FOREIGN KEY(project_id,student_id) REFERENCES project_members(project_id,user_id));
CREATE TABLE documents(id uuid PRIMARY KEY, contribution_id uuid REFERENCES contributions(id), owner_id uuid NOT NULL REFERENCES users(id), original_name text NOT NULL, storage_name text UNIQUE NOT NULL, mime_type text NOT NULL, byte_size integer NOT NULL CHECK(byte_size BETWEEN 1 AND 5242880), status text NOT NULL DEFAULT 'UPLOADED' CHECK(status IN ('UPLOADED','VERIFIED','RESTRICTED')), created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE profiles ADD CONSTRAINT photo_fk FOREIGN KEY(photo_document_id) REFERENCES documents(id);
-- Integration tables are populated by the weekly/hackathon module owners, never by students here.
CREATE TABLE weekly_updates(id uuid PRIMARY KEY, student_id uuid NOT NULL REFERENCES users(id), project_id uuid NOT NULL REFERENCES projects(id), week_start date NOT NULL, status text NOT NULL CHECK(status IN ('DRAFT','SUBMITTED','UNDER_REVIEW','REVISION_REQUIRED','VERIFIED')), UNIQUE(student_id,project_id,week_start));
CREATE TABLE hackathon_participations(id uuid PRIMARY KEY, student_id uuid NOT NULL REFERENCES users(id), event_name text NOT NULL, event_date date NOT NULL, status text NOT NULL CHECK(status IN ('REGISTERED','PARTICIPATED','VERIFIED')));
CREATE TABLE achievements(id uuid PRIMARY KEY, student_id uuid NOT NULL REFERENCES users(id), title text NOT NULL, achieved_on date NOT NULL, status text NOT NULL CHECK(status IN ('SUBMITTED','VERIFIED')));
CREATE TABLE notifications(id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), message text NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, actor_id uuid REFERENCES users(id), action text NOT NULL, target_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_user_idx ON sessions(user_id);
CREATE INDEX members_student_idx ON project_members(user_id);
CREATE INDEX contributions_student_idx ON contributions(student_id,contribution_date);
CREATE INDEX notifications_user_idx ON notifications(user_id,created_at DESC);
CREATE INDEX weekly_student_idx ON weekly_updates(student_id,week_start);
COMMIT;
